head.script:
scwin.trigger1_onclick = function(e) {
    var obj = {
        "id": "test123",
        "title": "test123",
        "start": "20180720",
        "end": "20180721"
    };
    schdule1.addSchedule(obj);
};
scwin.trigger2_onclick = function(e) {
    schdule1.removeschedule("test123");
};
scwin.trigger3_onclick = function(e) {
    /*headerLeftBtn 왼쪽 위 (오늘)
    headerRightBtn:false 오른쪽 위(주일월)
    headerTitle:true 년월 */
    var opt = {
        headerLeftBtn: true,
        headerRightBtn: false,
        headerTitle: true
    };
    schdule1.setHeaderBtn(opt);
};
scwin.trigger4_onclick = function(e) {
    var opt = {
        "sun": {
            "header": {
                "color": "#ff0000"
            },
            "body": {
                "background-color": "#ff0000",
                "opacity": "0.2"
            },
            "num": {
                "color": "#ff0000"
            }
        },
        "sat": {
            "header": {
                "color": "#ff0000"
            },
            "body": {
                "background-color": "#ff0000",
                "opacity": "0.2"
            },
            "num": {
                "color": "#ff0000"
            }
        }
    };
    schdule1.setDayNameStyle(opt);
};
scwin.schdule1_onclick = function(retObj) {
    //debugger;
};
scwin.schdule1_onheaderbtnclick = function(retObj) {
    scwin.viewType = retObj.viewType;
};
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("set", "document.getElementsByClassName('fc-icon fc-icon-left-single-arrow')[0].click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.viewType", "month");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    /******************************************************************************
     * 프로그램명	 : 개발 가이드 샘플.[sui_scheduleCalendar 샘플]
     * ProgramID	 : sui_scheduleCalendar
     * 작성자		 : 홍길동
     * 작성일		 : 2015-12-30
     * 변경로그		 : 2015-12-30 최초 작성
     *******************************************************************************/
    if (!scwin.promise) {
        scwin.promise = {};
    }
    /**
     * 
     */
    /**
     * 
     */
    /**
     * 
     */
    /**
     * 
     */
    //schdule1.setHeaderBtn({headerLeftBtn:false,headerRightBtn:false,headerTitle:false});
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
